insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060126', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, calcule a derivada de $f(x)=\frac{x+1}{x+3}$. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601261', '40000000-0000-4000-8000-000000060126', 'A', '$\frac{2}{(x+3)^2}$', 1), ('50000000-0000-4000-8000-000000601262', '40000000-0000-4000-8000-000000060126', 'B', '$\frac{1}{x+3}$', 2), ('50000000-0000-4000-8000-000000601263', '40000000-0000-4000-8000-000000060126', 'C', '$\frac{-2}{(x+3)^2}$', 3), ('50000000-0000-4000-8000-000000601264', '40000000-0000-4000-8000-000000060126', 'D', '$\frac{x+1}{(x+3)^2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060126', '50000000-0000-4000-8000-000000601261') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060126', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601261', '40000000-0000-4000-8000-000000060126', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601262', '40000000-0000-4000-8000-000000060126', 'Use a regra do quociente: derivada do numerador vezes denominador, menos numerador vezes derivada do denominador.', 2), ('60000000-0000-4000-8000-000000601263', '40000000-0000-4000-8000-000000060126', 'As duas expressões lineares têm derivada igual a 1.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060126', '$f^{\prime}(x)=\frac{2}{(x+3)^2}.$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra do quociente exige atenção à ordem da subtração. Neste caso, as derivadas das duas expressões lineares são iguais a 1, então os termos com x se cancelam e resta apenas a diferença entre as constantes. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601261', '40000000-0000-4000-8000-000000060126', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601262', '40000000-0000-4000-8000-000000060126', 'Nomeie as partes', '$u=x+1, v=x+3 e u^{\prime}=v^{\prime}=1.$', 2), ('70000000-0000-4000-8000-000000601263', '40000000-0000-4000-8000-000000060126', 'Aplique a regra', '$f^{\prime}(x)=\frac{(x+3)-(x+1)}{(x+3)^2}.$', 3), ('70000000-0000-4000-8000-000000601264', '40000000-0000-4000-8000-000000060126', 'Simplifique', '$f^{\prime}(x)=\frac{2}{(x+3)^2}.$', 4), ('70000000-0000-4000-8000-000000601265', '40000000-0000-4000-8000-000000060126', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060127', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, qual é a derivada de $f(x)=(2x+4)^6$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601271', '40000000-0000-4000-8000-000000060127', 'A', '$12(2x+4)^5$', 1), ('50000000-0000-4000-8000-000000601272', '40000000-0000-4000-8000-000000060127', 'B', '$6(2x+4)^5$', 2), ('50000000-0000-4000-8000-000000601273', '40000000-0000-4000-8000-000000060127', 'C', '$12(2x+4)^6$', 3), ('50000000-0000-4000-8000-000000601274', '40000000-0000-4000-8000-000000060127', 'D', '$(2x+4)^5$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
