insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060145', '$f^{\prime}(1)=4$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601451', '40000000-0000-4000-8000-000000060145', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601452', '40000000-0000-4000-8000-000000060145', 'Derive a potência', '$(x^2)^{\prime}=2x.$', 2), ('70000000-0000-4000-8000-000000601453', '40000000-0000-4000-8000-000000060145', 'Derive o termo linear', '$(2x)^{\prime}=2.$', 3), ('70000000-0000-4000-8000-000000601454', '40000000-0000-4000-8000-000000060145', 'Avalie em 1', '$f^{\prime}(1)=2+2=4.$', 4), ('70000000-0000-4000-8000-000000601455', '40000000-0000-4000-8000-000000060145', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
