insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601471', '40000000-0000-4000-8000-000000060147', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601472', '40000000-0000-4000-8000-000000060147', 'A substituição inicial dá zero sobre zero.', 2), ('60000000-0000-4000-8000-000000601473', '40000000-0000-4000-8000-000000060147', 'Multiplique pela expressão conjugada $\sqrt{x+5}+3$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060147', '$1/6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A racionalização transforma a diferença de raízes em uma diferença de quadrados. Assim aparece o fator do denominador, que pode ser cancelado antes de avaliarmos a tendência no ponto. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601471', '40000000-0000-4000-8000-000000060147', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601472', '40000000-0000-4000-8000-000000060147', 'Use o conjugado', 'Multiplique numerador e denominador por $\sqrt{x+5}+3$.', 2), ('70000000-0000-4000-8000-000000601473', '40000000-0000-4000-8000-000000060147', 'Simplifique o numerador', '$(x+5)-9=x-4$.', 3), ('70000000-0000-4000-8000-000000601474', '40000000-0000-4000-8000-000000060147', 'Cancele e avalie', 'Resta $1/(\sqrt{x+5}+3)$, cujo limite é $1/6$.', 4), ('70000000-0000-4000-8000-000000601475', '40000000-0000-4000-8000-000000060147', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060148', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, partindo de $y=x^2$, qual transformação produz $g(x)=(x-4)^2+3$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601481', '40000000-0000-4000-8000-000000060148', 'A', 'Deslocar 4 unidades à direita e 3 para cima.', 1), ('50000000-0000-4000-8000-000000601482', '40000000-0000-4000-8000-000000060148', 'B', 'Deslocar 4 unidades à esquerda e 3 para cima.', 2), ('50000000-0000-4000-8000-000000601483', '40000000-0000-4000-8000-000000060148', 'C', 'Deslocar 3 unidades à direita e 4 para cima.', 3), ('50000000-0000-4000-8000-000000601484', '40000000-0000-4000-8000-000000060148', 'D', 'Refletir no eixo x e deslocar para cima.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
