insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601491', '40000000-0000-4000-8000-000000060149', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601492', '40000000-0000-4000-8000-000000060149', 'Para haver continuidade, o limite pela esquerda deve coincidir com o valor da função.', 2), ('60000000-0000-4000-8000-000000601493', '40000000-0000-4000-8000-000000060149', 'A expressão da esquerda vale x mais 5.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060149', '$c=10$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma função definida por partes, a continuidade no ponto de troca depende de três valores compatíveis: limite pela esquerda, limite pela direita e valor da função. Como o lado direito é constante c, basta escolher c igual ao valor que a expressão da esquerda se aproxima quando x tende ao ponto de corte. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601491', '40000000-0000-4000-8000-000000060149', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601492', '40000000-0000-4000-8000-000000060149', 'Identifique a informação', 'O possível salto ocorre no ponto $x=5$.', 2), ('70000000-0000-4000-8000-000000601493', '40000000-0000-4000-8000-000000060149', 'Escreva a condição', '$lim_{x\to5^-}(x+5)=5+5$.', 3), ('70000000-0000-4000-8000-000000601494', '40000000-0000-4000-8000-000000060149', 'Faça o cálculo', '$lim_{x\to5^-}f(x)=10$.', 4), ('70000000-0000-4000-8000-000000601495', '40000000-0000-4000-8000-000000060149', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060150', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Considere cuidadosamente os dados e para $f(x)=-x^2+4x$, em qual x ocorre o máximo global?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
