insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601511', '40000000-0000-4000-8000-000000060151', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601512', '40000000-0000-4000-8000-000000060151', 'Troque f de x por y e isole x.', 2), ('60000000-0000-4000-8000-000000601513', '40000000-0000-4000-8000-000000060151', 'A inversa desfaz a multiplicação por 4 e a subtração de 3.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060151', '$f^{-1}(x)=\frac{x+3}{4}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Para encontrar uma inversa, começamos com a saída y e recuperamos a entrada x. A ordem das operações precisa ser desfeita ao contrário: primeiro somamos o termo que havia sido subtraído, depois dividimos pelo coeficiente. A fórmula final pode ser conferida compondo f com sua inversa e obtendo x. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601511', '40000000-0000-4000-8000-000000060151', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601512', '40000000-0000-4000-8000-000000060151', 'Identifique a informação', '$y=4x-3$.', 2), ('70000000-0000-4000-8000-000000601513', '40000000-0000-4000-8000-000000060151', 'Escreva a condição', '$y+3=4x$.', 3), ('70000000-0000-4000-8000-000000601514', '40000000-0000-4000-8000-000000060151', 'Faça o cálculo', '$x=\frac{y+3}{4}$.', 4), ('70000000-0000-4000-8000-000000601515', '40000000-0000-4000-8000-000000060151', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060152', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-90$, partindo de $x_0=10$. Qual é $x_1$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601521', '40000000-0000-4000-8000-000000060152', 'A', '$\frac{190}{20}$', 1), ('50000000-0000-4000-8000-000000601522', '40000000-0000-4000-8000-000000060152', 'B', '$10$', 2), ('50000000-0000-4000-8000-000000601523', '40000000-0000-4000-8000-000000060152', 'C', '$9$', 3), ('50000000-0000-4000-8000-000000601524', '40000000-0000-4000-8000-000000060152', 'D', '$\frac{90}{10}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
