insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601621', '40000000-0000-4000-8000-000000060162', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601622', '40000000-0000-4000-8000-000000060162', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 2), ('60000000-0000-4000-8000-000000601623', '40000000-0000-4000-8000-000000060162', 'O termo somado fora da função controla o deslocamento vertical.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060162', 'Deslocar 5 unidades à direita e 4 para cima.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601621', '40000000-0000-4000-8000-000000060162', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601622', '40000000-0000-4000-8000-000000060162', 'Identifique a informação', '$g(x)=(x-5)^2+4$ vem de uma parábola padrão.', 2), ('70000000-0000-4000-8000-000000601623', '40000000-0000-4000-8000-000000060162', 'Escreva a condição', '$x-5$ controla a posição horizontal.', 3), ('70000000-0000-4000-8000-000000601624', '40000000-0000-4000-8000-000000060162', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(5,4)$.', 4), ('70000000-0000-4000-8000-000000601625', '40000000-0000-4000-8000-000000060162', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060163', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, para qual valor de $c$ a função $f(x)=\begin{cases}x+6,&x<6\\c,&x\ge6\end{cases}$ é contínua em $x=6$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601631', '40000000-0000-4000-8000-000000060163', 'A', '$12$', 1), ('50000000-0000-4000-8000-000000601632', '40000000-0000-4000-8000-000000060163', 'B', '$6$', 2), ('50000000-0000-4000-8000-000000601633', '40000000-0000-4000-8000-000000060163', 'C', '$13$', 3), ('50000000-0000-4000-8000-000000601634', '40000000-0000-4000-8000-000000060163', 'D', '$0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060163', '50000000-0000-4000-8000-000000601631') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060163', '30000000-0000-4000-8000-000000000019', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601631', '40000000-0000-4000-8000-000000060163', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601632', '40000000-0000-4000-8000-000000060163', 'Para haver continuidade, o limite pela esquerda deve coincidir com o valor da função.', 2), ('60000000-0000-4000-8000-000000601633', '40000000-0000-4000-8000-000000060163', 'A expressão da esquerda vale x mais 6.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060163', '$c=12$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma função definida por partes, a continuidade no ponto de troca depende de três valores compatíveis: limite pela esquerda, limite pela direita e valor da função. Como o lado direito é constante c, basta escolher c igual ao valor que a expressão da esquerda se aproxima quando x tende ao ponto de corte. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601631', '40000000-0000-4000-8000-000000060163', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601632', '40000000-0000-4000-8000-000000060163', 'Identifique a informação', 'O possível salto ocorre no ponto $x=6$.', 2), ('70000000-0000-4000-8000-000000601633', '40000000-0000-4000-8000-000000060163', 'Escreva a condição', '$lim_{x\to6^-}(x+6)=6+6$.', 3), ('70000000-0000-4000-8000-000000601634', '40000000-0000-4000-8000-000000060163', 'Faça o cálculo', '$lim_{x\to6^-}f(x)=12$.', 4), ('70000000-0000-4000-8000-000000601635', '40000000-0000-4000-8000-000000060163', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060164', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Em vez de começar pelas contas, para $f(x)=-x^2+6x$, em qual x ocorre o máximo global?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601641', '40000000-0000-4000-8000-000000060164', 'A', '$x=3$', 1), ('50000000-0000-4000-8000-000000601642', '40000000-0000-4000-8000-000000060164', 'B', '$x=6$', 2), ('50000000-0000-4000-8000-000000601643', '40000000-0000-4000-8000-000000060164', 'C', '$x=-3$', 3), ('50000000-0000-4000-8000-000000601644', '40000000-0000-4000-8000-000000060164', 'D', '$x=0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
