insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601651', '40000000-0000-4000-8000-000000060165', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601652', '40000000-0000-4000-8000-000000060165', 'Exponencie os dois lados com base e.', 2), ('60000000-0000-4000-8000-000000601653', '40000000-0000-4000-8000-000000060165', 'Lembre que o logaritmo natural só aceita entradas positivas.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060165', '$x=e^{4}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural e a exponencial de base e são funções inversas. Ao aplicar a exponencial aos dois lados, o logaritmo é desfeito e resta x. A solução encontrada é automaticamente positiva, portanto respeita o domínio do logaritmo e não exige descartar nenhuma raiz adicional. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601651', '40000000-0000-4000-8000-000000060165', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601652', '40000000-0000-4000-8000-000000060165', 'Identifique a informação', '$\ln(x)$ é definido somente para valores positivos de x.', 2), ('70000000-0000-4000-8000-000000601653', '40000000-0000-4000-8000-000000060165', 'Escreva a condição', '$e^{\ln(x)}=e^{4}$.', 3), ('70000000-0000-4000-8000-000000601654', '40000000-0000-4000-8000-000000060165', 'Faça o cálculo', '$x=e^{4}$.', 4), ('70000000-0000-4000-8000-000000601655', '40000000-0000-4000-8000-000000060165', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060166', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-110$, partindo de $x_0=11$. Qual é $x_1$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
