insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601661', '40000000-0000-4000-8000-000000060166', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601662', '40000000-0000-4000-8000-000000060166', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000601663', '40000000-0000-4000-8000-000000060166', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060166', '$x_1=\frac{231}{22}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601661', '40000000-0000-4000-8000-000000060166', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601662', '40000000-0000-4000-8000-000000060166', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000601663', '40000000-0000-4000-8000-000000060166', 'Aplique Newton', '$x_1=11-\frac{121-110}{2\cdot 11}.$', 3), ('70000000-0000-4000-8000-000000601664', '40000000-0000-4000-8000-000000060166', 'Simplifique', '$x_1=\frac{231}{22}.$', 4), ('70000000-0000-4000-8000-000000601665', '40000000-0000-4000-8000-000000060166', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060167', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, um retângulo tem perímetro 28 m. Qual deve ser a medida de cada lado para que sua área seja máxima?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601671', '40000000-0000-4000-8000-000000060167', 'A', '$7$ m', 1), ('50000000-0000-4000-8000-000000601672', '40000000-0000-4000-8000-000000060167', 'B', '$9$ m', 2), ('50000000-0000-4000-8000-000000601673', '40000000-0000-4000-8000-000000060167', 'C', '$4$ m', 3), ('50000000-0000-4000-8000-000000601674', '40000000-0000-4000-8000-000000060167', 'D', '$14$ m', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
