insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601711', '40000000-0000-4000-8000-000000060171', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601712', '40000000-0000-4000-8000-000000060171', 'Use a regra da potência.', 2), ('60000000-0000-4000-8000-000000601713', '40000000-0000-4000-8000-000000060171', 'O coeficiente original continua multiplicando o resultado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060171', '$f^{\prime}(x)=12x^3$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência multiplica o coeficiente pelo expoente e reduz esse expoente em uma unidade. Como a função tem um coeficiente externo, ele participa da multiplicação. É importante reduzir somente o expoente de x: alterar a potência sem ajustar o coeficiente produz um resultado que não devolve a função original ao ser integrado. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601711', '40000000-0000-4000-8000-000000060171', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601712', '40000000-0000-4000-8000-000000060171', 'Observe a estrutura', '$f(x)=3x^{4}$', 2), ('70000000-0000-4000-8000-000000601713', '40000000-0000-4000-8000-000000060171', 'Escolha a regra', 'O expoente é 31.', 3), ('70000000-0000-4000-8000-000000601714', '40000000-0000-4000-8000-000000060171', 'Calcule', '$f^{\prime}(x)=3\cdot4x^3$', 4), ('70000000-0000-4000-8000-000000601715', '40000000-0000-4000-8000-000000060171', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060172', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, qual é o domínio real de $f(x)=\sqrt{7-x}$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
