insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601751', '40000000-0000-4000-8000-000000060175', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601752', '40000000-0000-4000-8000-000000060175', 'A substituição inicial dá zero sobre zero.', 2), ('60000000-0000-4000-8000-000000601753', '40000000-0000-4000-8000-000000060175', 'Multiplique pela expressão conjugada $\sqrt{x+8}+4$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060175', '$1/8$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A racionalização transforma a diferença de raízes em uma diferença de quadrados. Assim aparece o fator do denominador, que pode ser cancelado antes de avaliarmos a tendência no ponto. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601751', '40000000-0000-4000-8000-000000060175', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601752', '40000000-0000-4000-8000-000000060175', 'Use o conjugado', 'Multiplique numerador e denominador por $\sqrt{x+8}+4$.', 2), ('70000000-0000-4000-8000-000000601753', '40000000-0000-4000-8000-000000060175', 'Simplifique o numerador', '$(x+8)-16=x-8$.', 3), ('70000000-0000-4000-8000-000000601754', '40000000-0000-4000-8000-000000060175', 'Cancele e avalie', 'Resta $1/(\sqrt{x+8}+4)$, cujo limite é $1/8$.', 4), ('70000000-0000-4000-8000-000000601755', '40000000-0000-4000-8000-000000060175', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
