insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601761', '40000000-0000-4000-8000-000000060176', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601762', '40000000-0000-4000-8000-000000060176', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 2), ('60000000-0000-4000-8000-000000601763', '40000000-0000-4000-8000-000000060176', 'O termo somado fora da função controla o deslocamento vertical.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060176', 'Deslocar 6 unidades à direita e 5 para cima.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601761', '40000000-0000-4000-8000-000000060176', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601762', '40000000-0000-4000-8000-000000060176', 'Identifique a informação', '$g(x)=(x-6)^2+5$ vem de uma parábola padrão.', 2), ('70000000-0000-4000-8000-000000601763', '40000000-0000-4000-8000-000000060176', 'Escreva a condição', '$x-6$ controla a posição horizontal.', 3), ('70000000-0000-4000-8000-000000601764', '40000000-0000-4000-8000-000000060176', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(6,5)$.', 4), ('70000000-0000-4000-8000-000000601765', '40000000-0000-4000-8000-000000060176', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060177', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Ao interpretar a situação proposta, para qual valor de $c$ a função $f(x)=\begin{cases}x+7,&x<7\\c,&x\ge7\end{cases}$ é contínua em $x=7$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601771', '40000000-0000-4000-8000-000000060177', 'A', '$14$', 1), ('50000000-0000-4000-8000-000000601772', '40000000-0000-4000-8000-000000060177', 'B', '$7$', 2), ('50000000-0000-4000-8000-000000601773', '40000000-0000-4000-8000-000000060177', 'C', '$15$', 3), ('50000000-0000-4000-8000-000000601774', '40000000-0000-4000-8000-000000060177', 'D', '$0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
