insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601811', '40000000-0000-4000-8000-000000060181', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601812', '40000000-0000-4000-8000-000000060181', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 2), ('60000000-0000-4000-8000-000000601813', '40000000-0000-4000-8000-000000060181', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060181', '$x=y=8$ m.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601811', '40000000-0000-4000-8000-000000060181', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601812', '40000000-0000-4000-8000-000000060181', 'Use o perímetro', '$2x+2y=32 \Rightarrow y=16-x.$', 2), ('70000000-0000-4000-8000-000000601813', '40000000-0000-4000-8000-000000060181', 'Escreva a área', '$A(x)=x(16-x).$', 3), ('70000000-0000-4000-8000-000000601814', '40000000-0000-4000-8000-000000060181', 'Localize o vértice', '$A^{\prime}(x)=16-2x=0 \Rightarrow x=8, y=8.$', 4), ('70000000-0000-4000-8000-000000601815', '40000000-0000-4000-8000-000000060181', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060182', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, calcule a derivada de $f(x)=\frac{x+5}{x+2}$. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601821', '40000000-0000-4000-8000-000000060182', 'A', '$\frac{-3}{(x+2)^2}$', 1), ('50000000-0000-4000-8000-000000601822', '40000000-0000-4000-8000-000000060182', 'B', '$\frac{1}{x+2}$', 2), ('50000000-0000-4000-8000-000000601823', '40000000-0000-4000-8000-000000060182', 'C', '$\frac{3}{(x+2)^2}$', 3), ('50000000-0000-4000-8000-000000601824', '40000000-0000-4000-8000-000000060182', 'D', '$\frac{x+5}{(x+2)^2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
