insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601861', '40000000-0000-4000-8000-000000060186', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601862', '40000000-0000-4000-8000-000000060186', 'Derive cada parcela do polinômio separadamente.', 2), ('60000000-0000-4000-8000-000000601863', '40000000-0000-4000-8000-000000060186', 'Depois de derivar, substitua x igual a 1.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060186', '$f^{\prime}(1)=7$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601861', '40000000-0000-4000-8000-000000060186', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601862', '40000000-0000-4000-8000-000000060186', 'Derive a potência', '$(x^2)^{\prime}=2x.$', 2), ('70000000-0000-4000-8000-000000601863', '40000000-0000-4000-8000-000000060186', 'Derive o termo linear', '$(5x)^{\prime}=5.$', 3), ('70000000-0000-4000-8000-000000601864', '40000000-0000-4000-8000-000000060186', 'Avalie em 1', '$f^{\prime}(1)=2+5=7.$', 4), ('70000000-0000-4000-8000-000000601865', '40000000-0000-4000-8000-000000060186', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060187', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, calcule $\lim_{x\to7}\frac{x^2-49}{x-7}$. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601871', '40000000-0000-4000-8000-000000060187', 'A', '$14$', 1), ('50000000-0000-4000-8000-000000601872', '40000000-0000-4000-8000-000000060187', 'B', '$7$', 2), ('50000000-0000-4000-8000-000000601873', '40000000-0000-4000-8000-000000060187', 'C', '$50$', 3), ('50000000-0000-4000-8000-000000601874', '40000000-0000-4000-8000-000000060187', 'D', 'Não existe.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
