insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601881', '40000000-0000-4000-8000-000000060188', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601882', '40000000-0000-4000-8000-000000060188', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 2), ('60000000-0000-4000-8000-000000601883', '40000000-0000-4000-8000-000000060188', 'O termo somado fora da função controla o deslocamento vertical.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060188', 'Deslocar 7 unidades à direita e 6 para cima.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601881', '40000000-0000-4000-8000-000000060188', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601882', '40000000-0000-4000-8000-000000060188', 'Identifique a informação', '$g(x)=(x-7)^2+6$ vem de uma parábola padrão.', 2), ('70000000-0000-4000-8000-000000601883', '40000000-0000-4000-8000-000000060188', 'Escreva a condição', '$x-7$ controla a posição horizontal.', 3), ('70000000-0000-4000-8000-000000601884', '40000000-0000-4000-8000-000000060188', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(7,6)$.', 4), ('70000000-0000-4000-8000-000000601885', '40000000-0000-4000-8000-000000060188', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060189', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em vez de começar pelas contas, para qual valor de $c$ a função $f(x)=\begin{cases}x+8,&x<8\\c,&x\ge8\end{cases}$ é contínua em $x=8$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601891', '40000000-0000-4000-8000-000000060189', 'A', '$16$', 1), ('50000000-0000-4000-8000-000000601892', '40000000-0000-4000-8000-000000060189', 'B', '$8$', 2), ('50000000-0000-4000-8000-000000601893', '40000000-0000-4000-8000-000000060189', 'C', '$17$', 3), ('50000000-0000-4000-8000-000000601894', '40000000-0000-4000-8000-000000060189', 'D', '$0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
