insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000602111', '40000000-0000-4000-8000-000000060211', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000602112', '40000000-0000-4000-8000-000000060211', 'A substituição direta produz a forma indeterminada zero sobre zero.', 2), ('60000000-0000-4000-8000-000000602113', '40000000-0000-4000-8000-000000060211', 'Fatore diferença de quadrados e simplifique antes de tomar o limite.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060211', '$18$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A forma zero sobre zero não é uma resposta: ela sinaliza que a expressão deve ser reorganizada. A diferença de quadrados revela um fator x menos a que pode ser cancelado fora do ponto problemático. Depois da simplificação, a função restante é contínua e pode ser avaliada diretamente no ponto de aproximação. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000602111', '40000000-0000-4000-8000-000000060211', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000602112', '40000000-0000-4000-8000-000000060211', 'Identifique a informação', 'Substituir 9 inicialmente gera zero sobre zero.', 2), ('70000000-0000-4000-8000-000000602113', '40000000-0000-4000-8000-000000060211', 'Escreva a condição', '$x^2-81=(x-9)(x+9)$.', 3), ('70000000-0000-4000-8000-000000602114', '40000000-0000-4000-8000-000000060211', 'Faça o cálculo', '$\frac{x^2-81}{x-9}=x+9,;x\ne9$.', 4), ('70000000-0000-4000-8000-000000602115', '40000000-0000-4000-8000-000000060211', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060212', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, partindo de $y=x^2$, qual transformação produz $g(x)=(x-9)^2+8$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000602121', '40000000-0000-4000-8000-000000060212', 'A', 'Deslocar 9 unidades à direita e 8 para cima.', 1), ('50000000-0000-4000-8000-000000602122', '40000000-0000-4000-8000-000000060212', 'B', 'Deslocar 9 unidades à esquerda e 8 para cima.', 2), ('50000000-0000-4000-8000-000000602123', '40000000-0000-4000-8000-000000060212', 'C', 'Deslocar 8 unidades à direita e 9 para cima.', 3), ('50000000-0000-4000-8000-000000602124', '40000000-0000-4000-8000-000000060212', 'D', 'Refletir no eixo x e deslocar para cima.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
