insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060216', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000602161', '40000000-0000-4000-8000-000000060216', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000602162', '40000000-0000-4000-8000-000000060216', 'Pontos do eixo x têm coordenada y igual a zero.', 2), ('60000000-0000-4000-8000-000000602163', '40000000-0000-4000-8000-000000060216', 'Iguale a função a zero e fatorize.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060216', '$(8,0)$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Interseções com o eixo x são zeros da função, pois nesses pontos a altura do gráfico é zero. Ao fatorar uma diferença de quadrados, encontramos duas raízes simétricas. A alternativa pedida apresenta a raiz positiva; verificar a substituição mostra que o valor da função realmente se anula, confirmando que o ponto pertence ao gráfico. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000602161', '40000000-0000-4000-8000-000000060216', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000602162', '40000000-0000-4000-8000-000000060216', 'Observe a estrutura', 'No eixo x, a coordenada vertical vale zero.', 2), ('70000000-0000-4000-8000-000000602163', '40000000-0000-4000-8000-000000060216', 'Escolha a regra', '$x^2-64=0$', 3), ('70000000-0000-4000-8000-000000602164', '40000000-0000-4000-8000-000000060216', 'Calcule', '$(x-8)(x+8)=0$', 4), ('70000000-0000-4000-8000-000000602165', '40000000-0000-4000-8000-000000060216', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060217', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, um retângulo tem perímetro 44 m. Qual deve ser a medida de cada lado para que sua área seja máxima?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
