insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060222', '$f^{\prime}(1)=10$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000602221', '40000000-0000-4000-8000-000000060222', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000602222', '40000000-0000-4000-8000-000000060222', 'Derive a potência', '$(x^2)^{\prime}=2x.$', 2), ('70000000-0000-4000-8000-000000602223', '40000000-0000-4000-8000-000000060222', 'Derive o termo linear', '$(8x)^{\prime}=8.$', 3), ('70000000-0000-4000-8000-000000602224', '40000000-0000-4000-8000-000000060222', 'Avalie em 1', '$f^{\prime}(1)=2+8=10.$', 4), ('70000000-0000-4000-8000-000000602225', '40000000-0000-4000-8000-000000060222', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060223', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, calcule $\lim_{x\to10}\frac{x^2-100}{x-10}$. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
