insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000602401', '40000000-0000-4000-8000-000000060240', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000602402', '40000000-0000-4000-8000-000000060240', 'Há uma função externa, o cubo, aplicada a uma função interna.', 2), ('60000000-0000-4000-8000-000000602403', '40000000-0000-4000-8000-000000060240', 'Multiplique a derivada da parte externa pela derivada de x ao quadrado mais n.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060240', '$g^{\prime}(x)=6x(x^2+9)^2$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada mede a taxa de variação instantânea. Em vez de apenas memorizar uma regra, é útil separar a expressão em partes, aplicar a regra apropriada e só então substituir o valor pedido. Essa ordem reduz erros de sinal e deixa claro o significado de cada etapa. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000602401', '40000000-0000-4000-8000-000000060240', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000602402', '40000000-0000-4000-8000-000000060240', 'Defina a parte interna', '$u=x^2+9.$', 2), ('70000000-0000-4000-8000-000000602403', '40000000-0000-4000-8000-000000060240', 'Derive a parte externa', '$(u^3)^{\prime}=3u^2.$', 3), ('70000000-0000-4000-8000-000000602404', '40000000-0000-4000-8000-000000060240', 'Multiplique por u linha', '$g^{\prime}(x)=3(x^2+9)^2\cdot 2x=6x(x^2+9)^2.$', 4), ('70000000-0000-4000-8000-000000602405', '40000000-0000-4000-8000-000000060240', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060241', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, calcule a derivada de $f(x)=9x^{10}$. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000602411', '40000000-0000-4000-8000-000000060241', 'A', '$90x^9$', 1), ('50000000-0000-4000-8000-000000602412', '40000000-0000-4000-8000-000000060241', 'B', '$9x^9$', 2), ('50000000-0000-4000-8000-000000602413', '40000000-0000-4000-8000-000000060241', 'C', '$90x^10$', 3), ('50000000-0000-4000-8000-000000602414', '40000000-0000-4000-8000-000000060241', 'D', '$11x^9$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060241', '50000000-0000-4000-8000-000000602411') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060241', '30000000-0000-4000-8000-000000000023', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000602411', '40000000-0000-4000-8000-000000060241', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000602412', '40000000-0000-4000-8000-000000060241', 'Use a regra da potência.', 2), ('60000000-0000-4000-8000-000000602413', '40000000-0000-4000-8000-000000060241', 'O coeficiente original continua multiplicando o resultado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060241', '$f^{\prime}(x)=90x^9$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência multiplica o coeficiente pelo expoente e reduz esse expoente em uma unidade. Como a função tem um coeficiente externo, ele participa da multiplicação. É importante reduzir somente o expoente de x: alterar a potência sem ajustar o coeficiente produz um resultado que não devolve a função original ao ser integrado. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000602411', '40000000-0000-4000-8000-000000060241', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000602412', '40000000-0000-4000-8000-000000060241', 'Observe a estrutura', '$f(x)=9x^{10}$', 2), ('70000000-0000-4000-8000-000000602413', '40000000-0000-4000-8000-000000060241', 'Escolha a regra', 'O expoente é 91.', 3), ('70000000-0000-4000-8000-000000602414', '40000000-0000-4000-8000-000000060241', 'Calcule', '$f^{\prime}(x)=9\cdot10x^9$', 4), ('70000000-0000-4000-8000-000000602415', '40000000-0000-4000-8000-000000060241', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
