insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000602441', '40000000-0000-4000-8000-000000060244', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000602442', '40000000-0000-4000-8000-000000060244', 'A parábola está na forma de vértice.', 2), ('60000000-0000-4000-8000-000000602443', '40000000-0000-4000-8000-000000060244', 'O coeficiente negativo indica abertura para baixo.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060244', '$x=3$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Uma parábola com sinal negativo abre para baixo, então seu vértice representa o maior valor possível. A forma quadrada mostra diretamente a posição horizontal do vértice: o quadrado é mínimo quando vale zero. Assim, maximizar a função equivale a escolher o valor de x que anula o termo entre parênteses. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000602441', '40000000-0000-4000-8000-000000060244', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000602442', '40000000-0000-4000-8000-000000060244', 'Observe a estrutura', '$f(x)=-(x-3)^2+2$', 2), ('70000000-0000-4000-8000-000000602443', '40000000-0000-4000-8000-000000060244', 'Escolha a regra', 'O quadrado é sempre não negativo.', 3), ('70000000-0000-4000-8000-000000602444', '40000000-0000-4000-8000-000000060244', 'Calcule', '$(x-3)^2=0$', 4), ('70000000-0000-4000-8000-000000602445', '40000000-0000-4000-8000-000000060244', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060245', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e se $f(x)=x(x+6)$, qual é $f^{\prime}(x)$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
