insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000602481', '40000000-0000-4000-8000-000000060248', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000602482', '40000000-0000-4000-8000-000000060248', 'Velocidade instantânea é a derivada da posição.', 2), ('60000000-0000-4000-8000-000000602483', '40000000-0000-4000-8000-000000060248', 'Derive antes de substituir o instante.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060248', '$v(2)=1$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada transforma a posição em velocidade porque mede a variação instantânea no tempo. O termo quadrático gera uma expressão linear e o termo linear contribui com uma constante negativa. Só depois de obter a regra geral de velocidade substituímos o instante pedido; isso evita usar uma taxa média por engano. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000602481', '40000000-0000-4000-8000-000000060248', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000602482', '40000000-0000-4000-8000-000000060248', 'Observe a estrutura', '$v(t)=s^{\prime}(t)$', 2), ('70000000-0000-4000-8000-000000602483', '40000000-0000-4000-8000-000000060248', 'Escolha a regra', '$s^{\prime}(t)=2t-3$', 3), ('70000000-0000-4000-8000-000000602484', '40000000-0000-4000-8000-000000060248', 'Calcule', '$v(2)=2\cdot2-3$', 4), ('70000000-0000-4000-8000-000000602485', '40000000-0000-4000-8000-000000060248', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060249', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000243', 'multiple_choice', 'hard', 'published', 'Em vez de começar pelas contas, em qual valor de $x$ a função $f(x)=-(x-2)^2+1$ atinge seu máximo?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
